import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import { DarkModeContext } from '../../context/darkModeContext';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import './friends.scss';

const Friends = () => {
  const { currentUser } = useContext(AuthContext);
  const { darkMode } = useContext(DarkModeContext);
  const navigate = useNavigate();
  const [friends, setFriends] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!currentUser) {
      navigate('/login');
      return;
    }

    console.log('Friends: currentUser=', JSON.stringify(currentUser, null, 2));

    const fetchFriends = async () => {
      const token = localStorage.getItem('token');
      if (!token) {
        setError('Please log in to view friends.');
        setLoading(false);
        return;
      }

      if (!currentUser._id) {
        console.error('Friends: currentUser._id is undefined');
        setError('User ID is missing.');
        setLoading(false);
        return;
      }

      try {
        console.log(`Friends: Fetching friends for user ID: ${currentUser._id}`);
        const res = await axios.get(`http://localhost:5000/api/users/${currentUser._id}`, {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('Friends: Fetched friends=', JSON.stringify(res.data.friends, null, 2));
        res.data.friends.forEach(friend => {
          console.log(`Friends: Friend ${friend.name} profilePicture=`, friend.profilePicture);
        });
        setFriends(res.data.friends || []);
      } catch (err) {
        console.error('Friends: Error fetching friends:', err.message);
        console.error('Friends: Response:', err.response?.data);
        setError(err.response?.data?.message || 'Failed to load friends.');
      } finally {
        setLoading(false);
      }
    };

    fetchFriends();
  }, [currentUser, navigate]);

  if (loading) return <div>Loading...</div>;
  if (error) return <div className="error">{error}</div>;

  return (
    <div className={`friends ${darkMode ? 'dark' : ''}`}>
      <h2>My Friends</h2>
      {friends.length === 0 ? (
        <p>No friends yet.</p>
      ) : (
        <div className="friends-list">
          {friends.map((friend) => (
            <div key={friend._id} className="friend-item">
              <img
                src={friend.profilePicture || '/assets/default-avatar.png'}
                alt={`${friend.name}'s avatar`}
                className="friend-avatar"
                onError={(e) => {
                  console.error(`Friends: Failed to load image for ${friend.name}: ${e.target.src}`);
                  e.target.src = '/assets/default-avatar.png';
                }}
              />
              <span>{friend.name}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default Friends;
